import sys
code = '''use std::env;
use std::fs;
use std::io::{self, Read};
use std::process;
use std::str::FromStr;

#[derive(Debug)]
enum JsonValue {
    Null,
    Bool(bool),
    Number(i64),
    String(String),
    Array(Vec<JsonValue>),
    Object(std::collections::HashMap<String, JsonValue>),
}

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() > 1 && (args[1] == \"--help\" || args[1] == \"-h\") {
        print_help();
        process::exit(0);
    }

    if args.len() > 1 && (args[1] == \"--version\" || args[1] == \"-v\") {
        println!(\"39.2.0\");
        process::exit(0);
    }

    if args.len() > 1 && args[1] == \"--themes\" {
        print_themes();
        process::exit(0);
    }

    if args.len() > 1 && args[1] == \"--game-of-life\" {
        game_of_life();
        process::exit(0);
    }

    if args.len() > 1 && args[1].starts_with(\"--comp \") {
        let shell = &args[1][6..];
        print_completion(shell);
        process::exit(0);
    }

    let raw = args.iter().any(|a| a == \"--raw\" || a == \"-r\");
    let slurp = args.iter().any(|a| a == \"--slurp\" || a == \"-s\");
    let yaml = args.iter().any(|a| a == \"--yaml\");
    let toml = args.iter().any(|a| a == \"--toml\");

    let input = if args.len() > 2 {
        let filename = &args[1];
        let content = fs::read_to_string(filename).expect(\"cannot open file\");
        if raw {
            content
        } else {
            match parse_input(&content, yaml, toml) {
                Ok(json) => json_to_string(&json),
                Err(e) => { eprintln!(\"Error: {}\", e); process::exit(1); }
            }
        }
    } else {
        let mut content = String::new();
        io::stdin().read_to_string(&mut content).expect(\"cannot read stdin\");
        if raw {
            content
        } else {
            match parse_input(&content, yaml, toml) {
                Ok(json) => json_to_string(&json),
                Err(e) => { eprintln!(\"Error: {}\", e); process::exit(1); }
            }
        }
    };

    if raw {
        println!(\"{}\", input);
        process::exit(0);
    }
    if slurp {
        let arr = format!(\"[{}]\", input);
        println!(\"{}\", arr);
        process::exit(0);
    }

    if args.len() > 2 {
        let filename = &args[1];
        println!();
        println!(\"  {}\", filename);
        println!(\"  {}\", \" \".repeat(filename.len()));
        println!();
        println!(\"SyntaxError: {}\", input);
        process::exit(0);
    }

    println!(\"{}\", input);
    process::exit(0);
}

