    println!("    -v, --version         print version");
    println!("    --themes              print themes");
    println!("    --comp <shell>        print completion script");
    println!("    -r, --raw             treat input as a raw string");
    println!("    -s, --slurp           read all inputs into an array");
    println!("    --yaml                parse input as YAML");
